from itertools import permutations
from hashlib import sha256

CASES = [(3, 3), (3, 4), (4, 3)]

def norm(parts):
    parts = tuple(x for x in parts if x)
    assert all(x > 0 for x in parts)
    assert all(parts[k] >= parts[k+1] for k in range(len(parts)-1))
    return parts

def size(part):
    return sum(part)

def contains(mu, lam):
    return all((mu[k] if k < len(mu) else 0) >= x for k, x in enumerate(lam))

def in_box(mu, width, height):
    return len(mu) <= height and (not mu or mu[0] <= width)

def horizontal_strip(lam, mu):
    # mu/lam has at most one box in every column iff mu_{k+1}<=lam_k.
    if not contains(mu, lam):
        return False
    L = list(lam) + [0] * (len(mu) + 1 - len(lam))
    M = list(mu) + [0] * (len(mu) + 1 - len(mu))
    return all(M[k+1] <= L[k] for k in range(len(mu)))

def all_partitions_bounded(total, width, height, maximum=None):
    if maximum is None:
        maximum = width
    if height == 0:
        if total == 0:
            yield ()
        return
    for first in range(min(maximum, width, total), -1, -1):
        for tail in all_partitions_bounded(total-first, width, height-1, first):
            yield norm((first,) + tail)

def interval_partitions(i, j, degree):
    lower = (i,) * j
    upper_width, upper_height = i+1, j+1
    ans = []
    for mu in all_partitions_bounded(degree, upper_width, upper_height):
        if contains(mu, lower):
            ans.append(mu)
    return sorted(set(ans))

def pieri(lam, ell, columns, width, height):
    out = []
    for mu in all_partitions_bounded(size(lam)+ell, width, height):
        if horizontal_strip(lam, mu):
            out.append(mu)
    return [1 if c in out else 0 for c in columns]

def determinant(mat):
    n = len(mat)
    assert all(len(row) == n for row in mat)
    total = 0
    for p in permutations(range(n)):
        inv = sum(p[a] > p[b] for a in range(n) for b in range(a+1, n))
        total += (-1 if inv % 2 else 1) * __import__('math').prod(mat[r][p[r]] for r in range(n))
    return total

def P(i, j, x, y):
    return norm((i+1,) * x + (i,) * (j-x) + ((y,) if y else ()))

print('INPUT_CASES:', CASES)
print('MODEL: partitions mu with i^j contained in mu contained in (i+1)^(j+1); Pieri via exact horizontal-strip enumeration')
column_count = row_count = named_count = minor_count = 0
for i, j in CASES:
    d = i*j
    columns = interval_partitions(i, j, d+4)
    expected_columns = [P(i, j, x, 4-x) for x in range(5)
                        if x <= j and 4-x <= i]
    assert columns == sorted(expected_columns)
    available = [x for x in range(5) if P(i, j, x, 4-x) in columns]
    print('CASE:', (i, j))
    print('COLUMNS_C0_TO_C4_AVAILABLE:', available)
    print('COLUMNS:', columns)
    all_rows = []
    for ell in range(1, 5):
        sources = interval_partitions(i, j, d+4-ell)
        expected_sources = [P(i, j, x, 4-ell-x) for x in range(5-ell)
                            if x <= j and 4-ell-x <= i]
        assert sources == sorted(expected_sources)
        for lam in sources:
            x = next(t for t in range(5-ell) if P(i, j, t, 4-ell-t) == lam)
            vec = pieri(lam, ell, columns, i+1, j+1)
            expected = [1 if c in (P(i,j,x,4-x), P(i,j,x+1,3-x)) else 0 for c in columns]
            assert vec == expected
            all_rows.append((ell, x, vec))
            named_count += 1
    all_rows.sort()
    print('ALL_ROWS_(ell,x,vector):', all_rows)
    if (i, j) == (3, 3):
        selected_keys = [(4, 0), (2, 2), (1, 3)]
    else:
        selected_keys = [(4, 0), (3, 1), (2, 2), (1, 3)]
    lookup = {(ell, x): vec for ell, x, vec in all_rows}
    selected = [lookup[key] for key in selected_keys]
    det = determinant(selected)
    assert det == 1
    print('SELECTED_ROWS_(ell,x):', selected_keys)
    print('SELECTED_MATRIX:', selected)
    print('DETERMINANT:', det)
    column_count += len(columns)
    row_count += len(all_rows)
    minor_count += 1
print('INTERVAL_COLUMNS_CHECKED:', column_count)
print('ALL_PRODUCT_ROWS_CHECKED:', row_count)
print('NAMED_PIERI_ROWS_CHECKED:', named_count)
print('SELECTED_MINORS_CHECKED:', minor_count)
print('RESULT: PASS')
